WITH src AS (SELECT * FROM suppliers WHERE city IN ('Bangkok', 'Berlin', 'Chiang Mai')), agg AS (SELECT CASE WHEN country IN ('SG', 'TH') THEN 'group_a' ELSE 'other' END country_group, SUM(CASE WHEN country = 'TH' THEN rating ELSE 0 END) th_rating, COUNT(CASE WHEN city = 'Berlin' THEN 1 END) berlin_count FROM src GROUP BY CASE WHEN country IN ('SG', 'TH') THEN 'group_a' ELSE 'other' END) SELECT country_group, th_rating, berlin_count FROM agg WHERE berlin_count > 9 ORDER BY th_rating DESC, berlin_count DESC, country_group LIMIT 1
